INSERT INTO public.kb_entries(id,topic_id,question,answer,keywords,link_href,link_label,status,source)
SELECT e->>0, CASE WHEN e->>0 LIKE 'chg-%' THEN 'ev-charging' WHEN e->>0 LIKE 'car-%' THEN 'ev-hybrid' ELSE 'academy' END, e->>1,e->>2,ARRAY(SELECT jsonb_array_elements_text(e->3)),nullif(e->>4,''),nullif(e->>5,''),'published','site'
FROM jsonb_array_elements($seed$[
["chg-what-offer","What EV charging services does GET Energy offer?","GET Energy is developing EV charging for Nigeria: AC destination charging (homes, offices, hotels, malls, estates), DC fast charging (highways, hubs, fleet depots, terminals, service stations), fleet charging, and solar-assisted charging with battery storage. The network is in development, so tell us your location and needs and our team will assess them.",["charger","charging point","station","services","offer"],"/solutions/ev-charging","EV charging"],
["chg-where","Where are GET Energy's charging stations? Is there one near me?","GET Energy's public charging network is not operating yet. Sites are being developed with property hosts, starting in Lagos. Share your area and we will let you know when a location near you is confirmed.",["near me","location","map","find","lagos","abuja","nearest","open"],"/solutions/ev-charging","EV charging"],
["chg-vision-400","What is GET Vision 400?","GET Vision 400 is GET Energy's strategic programme to develop up to 400 EV charging points across Nigeria by 2029, starting in Lagos. It is a target, not existing infrastructure: each site depends on a host partnership, technical feasibility, financing and approvals.",["vision 400","400 stations","2029","network","plan","nigeria"],"/solutions/ev-charging","EV charging"],
["chg-host","Can I host a GET Energy charging station on my property?","Yes, we welcome hosts such as fuel stations, malls, hotels, hospitals, universities, estates, offices, fleet depots and transport terminals. Under GET Energy's standard host model, GET Energy and its partners can provide the charging equipment at no equipment cost to the host, with a share of charging revenue. Every site is subject to assessment, approvals and a written agreement.",["host","property","landlord","my land","partner","revenue share","install at my","business premises"],"/solutions/ev-charging#enquire","Become a charging location partner"],
["chg-host-cost","How much does it cost a host to have a charging station installed?","Under the standard host model there is no equipment cost to the host: GET Energy and its partners fund and operate the chargers and share charging revenue with the host. Some sites may need electrical upgrades; these are agreed case by case after a site assessment. Hosts who prefer to buy their own chargers can ask for that option.",["cost","free","price","pay","host fee","investment"],"/solutions/ev-charging#enquire","Become a charging location partner"],
["chg-host-process","What happens after I submit my property as a charging location?","Our team reviews the location, then arranges a site visit to check parking, access, power supply and visibility. If the site fits, we propose the charger mix (AC and/or DC) and the commercial terms, and agree everything in writing before any installation. Submitting a site is not a commitment for either side.",["process","steps","next","after submit","site visit","assessment"],"/solutions/ev-charging#enquire","Become a charging location partner"],
["chg-ac-dc","What is the difference between AC and DC charging?","AC chargers (usually about 7–22 kW) charge through the car's own on-board charger, so they are slower and suit places where cars park for hours: homes, offices, hotels and malls. DC fast chargers (often 30–180 kW or more) feed the battery directly and suit quick top-ups on highways, at hubs and for fleets. How fast a car charges also depends on what the car itself accepts.",["ac","dc","fast charger","rapid","slow","level 2","kw","difference"],"",""],
["chg-time","How long does it take to charge an electric car?","It depends on the battery size, the charger's power and the car's limits. As a rough guide, a car with a 60 kWh battery takes about 8–9 hours from nearly empty on a 7 kW AC charger, and roughly 40–60 minutes to about 80% on a DC fast charger the car can fully use. Charging usually slows down above 80%.",["how long","hours","minutes","charging time","speed","full charge","80%"],"",""],
["chg-connectors","Which plug or connector does my car need?","Common connectors are Type 2 (AC) and CCS2 (DC) on European-specification cars, and GB/T (AC and DC) on many Chinese-specification cars, which are common in Nigeria. Check your car's charging port and manual before buying a charger. When we assess a home, office or site, we match the charger to the vehicles that will use it.",["plug","connector","type 2","ccs","ccs2","gbt","gb/t","socket","compatible","chademo"],"",""],
["chg-cost-to-charge","How much will it cost to charge at a GET Energy station?","Charging tariffs have not been published yet because the network is still in development. Prices will depend on the site, the charger type and the cost of electricity there. We will publish clear per-kWh prices before any station opens.",["price","tariff","per kwh","cost to charge","how much","naira"],"/solutions/ev-charging","EV charging"],
["chg-payment","How will I pay for charging?","Payments will be handled through GET Energy's charging platform, with a single dashboard for the network. Payment options will be announced when the first stations open; no charging payments are being taken yet.",["pay","payment","app","card","transfer","wallet","dashboard"],"/solutions/ev-charging","EV charging"],
["chg-home","Can GET Energy install a charger at my home?","Yes. GET Energy arranges home AC charger installation. We first check your car, your electrical supply and where the charger will go, then recommend a suitable unit (usually 7 kW single-phase, or up to 22 kW on three-phase if your car supports it) and quote for supply and installation. Installation is done by qualified electricians with protection and earthing to standard.",["home charger","wallbox","house","residential","install","garage","estate"],"/contact?service=ev-charging","Request a home charger"],
["chg-socket","Can I charge my electric car from a normal wall socket?","Many cars come with a portable cable for a household socket, but it is very slow (often around 2–3 kW) and should only be used on a sound, dedicated circuit checked by a qualified electrician. Avoid extension cords and adaptors. For daily use, a properly installed home charger is safer and faster.",["wall socket","13 amp","plug in at home","extension","granny cable","portable charger"],"",""],
["chg-power-outage","What about power outages? Can charging work without the grid?","Grid supply in Nigeria can be unreliable, so GET Energy designs charging with backup options: solar PV, battery storage and smart energy management, alongside the grid where available. The right mix is chosen per site after an assessment.",["nepa","light","outage","grid","blackout","solar","generator","backup","power supply"],"/solutions/ev-charging","EV charging"],
["chg-solar","Can an EV be charged with solar power?","Yes. Solar PV with battery storage can charge EVs, especially at homes, offices and depots where cars park during the day. GET Energy offers solar-assisted charging designs; the system size depends on how much you drive and how much sun and roof or land space you have.",["solar","panels","pv","renewable","off-grid","battery storage"],"/solutions/ev-charging","EV charging"],
["chg-fleet","Do you provide charging for fleets?","Yes. For logistics, ride-hailing, bus, corporate and government fleets, GET Energy plans depot and hub charging sized to your routes and schedules, with energy management and driver training. We start with a fleet energy assessment.",["fleet","company cars","logistics","bus","ride-hailing","depot","taxi","delivery"],"/solutions/fleet-energy-transition","Fleet energy transition"],
["chg-safety","Is EV charging safe?","Yes, when chargers are certified and installed correctly with proper protection, earthing and a dedicated circuit. Do not use damaged cables, adaptors or extension leads. If you see sparks, smoke, a burning smell or overheating, stop charging if it is safe to do so, keep people away and call qualified personnel.",["safe","safety","fire","rain","shock","danger"],"",""],
["chg-rain","Can I charge my car in the rain?","Yes. EV chargers and charging ports are designed to be used outdoors and in the rain. Keep connectors clean, do not use damaged cables, and never use household extension leads outside.",["rain","wet","water","outdoor","weather"],"",""],
["chg-maintenance","Who maintains the chargers?","GET Energy and its technical partners operate and maintain the chargers they install, with remote monitoring through the charging platform. For chargers you own, GET Energy can provide technical support and maintenance on request.",["maintenance","repair","broken","faulty charger","support","service"],"/solutions/ev-hybrid-services","EV & hybrid technical services"],
["chg-invest","Can I invest in GET Energy's EV charging network?","GET Energy works with investors and financing partners on its charging programme. Share your interest on the Invest page and our team will discuss options. Any opportunity is subject to due diligence and agreement; returns are never guaranteed.",["invest","investor","fund","finance","partnership","returns"],"/invest","Invest"],
["car-types","What is the difference between an EV, a hybrid and a plug-in hybrid?","An electric vehicle (EV or BEV) runs only on a battery and must be charged. A hybrid (HEV) has a petrol engine plus a small battery that charges itself while driving, so you never plug it in. A plug-in hybrid (PHEV) has a bigger battery you can charge for electric-only trips, plus a petrol engine for longer journeys.",["bev","hev","phev","hybrid","plug-in","difference","types","electric car"],"",""],
["car-buy","Does GET Energy sell electric and hybrid cars?","Yes. GET Energy can source electric and hybrid vehicles for individuals, businesses and fleets through its vehicle partners, and can pair the vehicle with a home or depot charger. Tell us the type of vehicle, budget and number of units; availability, price and delivery time are confirmed by our team in a written quotation.",["buy","sell","purchase","price","dealer","import","order","car sales"],"/ev","EV & mobility"],
["car-which","Should I choose an electric car or a hybrid?","If you can charge at home or work and mostly drive within the city, an EV gives the lowest running costs. If charging access is limited or you drive long distances often, a hybrid or plug-in hybrid is a practical first step. We can help you compare based on your daily distance and where the car parks.",["which","better","choose","recommend","best","advice"],"/ev","EV & mobility"],
["car-range","How far can an electric car go on one charge?","Most modern EVs cover roughly 250–500 km per charge, depending on the model and battery size. Real range drops with high speed, heavy loads, heavy air-conditioning use and hot weather, so plan with a margin.",["range","km","distance","how far","one charge","mileage"],"",""],
["car-running-cost","Is an electric car cheaper to run than a petrol car?","Usually yes. Electricity per kilometre generally costs less than petrol, and EVs need less routine maintenance (no oil changes, fewer moving parts). The saving depends on your electricity source and tariff; charging from a generator is much more expensive than grid or solar.",["cheaper","save","running cost","fuel cost","petrol price","economy"],"",""],
["car-hybrid-charge","Do I need to charge a hybrid car?","A standard hybrid (HEV) never needs plugging in; it charges its battery from the engine and braking. A plug-in hybrid (PHEV) should be charged regularly to get its fuel savings, but it still drives on petrol if the battery is empty.",["hybrid","charge hybrid","plug","self-charging"],"",""],
["car-battery-life","How long does an EV or hybrid battery last?","Vehicle batteries are designed to last many years; manufacturers' battery warranties are often around 8 years, but terms vary by brand and model, so check the specific warranty. Battery life is helped by avoiding constant charging to 100%, avoiding very deep discharge, and parking in shade in hot weather.",["battery life","warranty","degradation","replace battery","years"],"",""],
["car-heat","Do electric cars work well in Nigeria's heat?","Yes, modern EVs have thermal-management systems for hot climates. Heat can reduce range slightly and speed up battery ageing over time, so park in shade where possible and follow the maker's charging advice.",["heat","hot","climate","temperature","nigeria weather","sun"],"",""],
["car-flood","Is it safe to drive an electric car through flood water?","EV battery packs are sealed, but no car should be driven through deep or fast-moving water. Follow the maker's wading limits. If a car has been submerged, do not drive or charge it; have it inspected by qualified EV technicians first.",["flood","water","rain","submerged","wading"],"",""],
["car-service","Where can I service or repair my electric or hybrid car?","GET Energy is developing EV and hybrid technical services: diagnostics, high-voltage system inspection, battery health checks, charging-system and charging-port repair, preventive maintenance and fleet maintenance. Send a request with your vehicle make and model and our team will confirm what can be done.",["service","repair","mechanic","maintenance","workshop","diagnostics","fault"],"/solutions/ev-hybrid-services","EV & hybrid technical services"],
["car-battery-check","Can you check the health of a used EV's battery before I buy it?","Battery health assessment is part of the EV and hybrid technical services GET Energy is developing. Send us the vehicle details and we will confirm whether we can assess it and how. Battery refurbishment and remanufacturing are not offered at present.",["used ev","second hand","battery health","soh","inspection","tokunbo"],"/solutions/ev-hybrid-services","EV & hybrid technical services"],
["car-fleet","Can you help my company move its fleet to electric or hybrid vehicles?","Yes. GET Energy's fleet energy transition starts with a fleet energy audit and vehicle assessment, compares running costs, then plans vehicles, charging or CNG infrastructure, driver and technician training, and maintenance. Request a fleet assessment to begin.",["fleet","company","corporate","transition","logistics","buses","taxis"],"/solutions/fleet-energy-transition","Fleet energy transition"],
["car-cng-vs-ev","Should I convert to CNG or switch to an electric car?","Both cut fuel costs. CNG conversion keeps your current petrol car and adds a gas system, which suits high-mileage drivers near CNG refuelling. An EV suits drivers who can charge at home or work. GET Energy works on both and can advise based on your vehicle, mileage and location.",["cng","gas","conversion","compare","alternative fuel"],"/cng-conversion","CNG conversion"],
["car-finance","Can I buy an electric car on instalments or with financing?","GET Energy works with financing partners and can discuss financing options when it prepares your vehicle quotation, especially for businesses and fleets. Financing is subject to the partner's approval; nothing is guaranteed until agreed in writing.",["finance","loan","instalment","installment","lease","pay small small"],"/ev","EV & mobility"],
["acad-what","What is GET Energy Academy?","GET Energy Academy for Green Skills & Certification is GET Energy's training line for the green economy. It lists 64 offerings: 58 programmes and 6 career pathways across solar and storage, mini-grids, EV and mobility, CNG, energy efficiency, HSE, project finance, entrepreneurship and professional skills.",["academy","training","school","courses","green skills","get academy"],"/training-certification","GET Energy Academy"],
["acad-status","When does the next Academy training start?","All programmes currently have a waiting list open. Cohort dates, venues and final fees have not been confirmed yet. Join the waiting list for the programme you want and the team will contact you when the next cohort is scheduled.",["start","date","when","next class","cohort","schedule","intake"],"/training-certification/waitlist","Join the waiting list"],
["acad-ev-courses","Which EV and mobility courses does the Academy offer?","EV Charging Infrastructure (5 days), EV & Hybrid Vehicle Fundamentals (5 days), Green Mobility Infrastructure (3 days), and the EV Charging Technician Pathway (3–4 weeks), which combines electrical safety, EV charging, battery storage, smart metering and HSE. All are on the waiting list.",["ev course","ev training","charging course","hybrid training","mobility","technician"],"/training-certification/programmes/ev-charging-infrastructure","EV Charging Infrastructure"],
["acad-ev-fees","How much do the EV courses cost?","Proposed fees, to be confirmed: EV Charging Infrastructure ₦250,000; EV & Hybrid Vehicle Fundamentals ₦250,000; Green Mobility Infrastructure ₦175,000; EV Charging Technician Pathway ₦600,000. Partner examination or certification fees, where they apply, are separate.",["fee","price","cost","how much","naira","ev course fee"],"/training-certification/waitlist","Join the waiting list"],
["acad-fees-general","How much do Academy programmes cost?","Each programme lists a proposed fee, to be confirmed, ranging from about ₦85,000 for 2-day professional-skills courses to ₦850,000 for the Mini-Grid Professional Pathway. Final fees are confirmed with the cohort, and any partner examination or certification fees are separate. Ask about a specific programme for its proposed fee.",["fee","price","cost","tuition","how much"],"/training-certification","GET Energy Academy"],
["acad-solar","Do you have solar installation training?","Yes: Solar PV Installation & Supervision (20 days), Solar-Plus-Storage Design & Operations (10 days), Battery Energy Storage Systems (5 days), Distributed Renewable Energy Systems (10 days), and the Solar Technician Pathway (4–6 weeks). All are on the waiting list.",["solar","pv","installer","inverter","battery","bess"],"/training-certification/programmes/solar-pv-installation-supervision","Solar PV Installation & Supervision"],
["acad-cng","Do you offer CNG training?","Yes: CNG Technical Fundamentals (5 days), CNG Vehicle & Fleet Transition (3 days), CNG Refuelling Infrastructure (5 days), and the CNG Technician Pathway (3–4 weeks). All are on the waiting list.",["cng","gas","conversion training","technician"],"/training-certification/programmes/cng-technical-fundamentals","CNG Technical Fundamentals"],
["acad-certificate","Will I get a certificate?","Participants who complete a programme receive a GET Energy Academy certificate of completion. Some programmes may also lead to certification with recognised training or awarding partners; the awarding body, assessment and any separate exam fee depend on the programme and are confirmed before enrolment. No accreditation is claimed until confirmed.",["certificate","certification","accredited","recognised","award","qualification"],"/training-certification","GET Energy Academy"],
["acad-verify","How can an employer verify a GET Energy Academy certificate?","Use the certificate verification page and enter the certificate details shown on the document.",["verify","check certificate","employer","authentic","validation"],"/training-certification/verify","Verify a certificate"],
["acad-practical","Is the training practical or only theory?","Technical programmes are designed to be practical, with hands-on sessions delivered with approved technical partners such as NAPTIN for selected programmes, subject to confirmation for each cohort. Business, entrepreneurship and professional-skills courses are delivered by GET Energy Academy.",["practical","hands-on","theory","naptin","workshop","lab"],"/training-certification","GET Energy Academy"],
["acad-online","Can I take the training online?","Delivery mode depends on the programme: business and professional-skills courses suit online delivery, while technical programmes need in-person practical sessions. Tell us your preferred mode when you join the waiting list.",["online","virtual","remote","zoom","in person","physical","location","venue"],"/training-certification/waitlist","Join the waiting list"],
["acad-entry","What qualifications do I need to join a programme?","Entry requirements depend on the programme. Most introductory and professional-skills courses are open to anyone with basic literacy; technical courses suit technicians, engineers, graduates and people with some electrical background. If you are unsure, tell us your background and goal and we will suggest suitable programmes.",["requirement","qualification","eligible","who can","beginner","experience","background"],"/training-certification","GET Energy Academy"],
["acad-choose","I don't know which course to take. Can you advise me?","Yes. Tell us your goal (a technical job, career growth, starting an energy business, becoming a technician, management skills or entering the green economy) and your background, and SOPHIA or the team will suggest two to four suitable programmes.",["advise","which course","recommend","career","confused","help me choose"],"/training-certification","GET Energy Academy"],
["acad-corporate","Can you train our company staff?","Yes. GET Energy Academy offers corporate training tailored to your team: topic, number of participants, staff level, dates, delivery mode and whether certification or assessment is needed. Request corporate training to start scoping.",["corporate","staff","company","team","in-house","employees","organisation"],"/training-certification/corporate","Corporate training"],
["acad-pay","How do I pay for a course?","Online payment for Academy programmes is not open yet. Join the waiting list; when your cohort is confirmed, the team will share the final fee and how to pay. Do not pay anyone claiming to collect Academy fees without written confirmation from GET Energy.",["pay","payment","bank","transfer","register","enrol","enroll"],"/training-certification/waitlist","Join the waiting list"],
["acad-jobs","Will the Academy guarantee me a job?","No job is guaranteed. The programmes are designed to build practical, in-demand green-energy skills, and the Green Jobs & Career Readiness course helps with CVs, interviews and career pathways.",["job","employment","placement","career","work after"],"/training-certification/programmes/green-jobs-career-readiness","Green Jobs & Career Readiness"],
["acad-entrepreneur","Do you have training for starting a green energy business?","Yes: Green Energy Entrepreneurship (5 days), GreenTech Entrepreneurship (5 days), the GET Energy GreenTech Launchpad (10–12 weeks) and the GreenTech Founder Pathway (8–12 weeks), covering customer discovery, business models, pricing, project finance and investor readiness.",["business","entrepreneur","startup","start my own","founder","launchpad"],"/training-certification/programmes/get-energy-greentech-launchpad","GreenTech Launchpad"]
]$seed$::jsonb) e ON CONFLICT(id) DO NOTHING;